def tr(lang: str, key: str, **fmt) -> str:
    entry = S.get(key)
    text = key if entry is None else (entry.get(lang) or entry.get("fr") or key)
    if fmt:
        try:
            return text.format(**fmt)
        except (KeyError, IndexError, ValueError):
            return text
    return text
